#[tokio::test(flavor = "multi_thread")]
async fn migration_0056_backfills_terminal_timestamps_from_updated_at() -> TestResult {
    let (_pg, store) = connect_pg().await?;
    create_rss_app_role_for_migration_test(&store).await?;
    sqlx::raw_sql(
        r#"
        CREATE TABLE outbox (
            event_id text PRIMARY KEY,
            tenant_id uuid NOT NULL,
            domain text NOT NULL,
            topic text NOT NULL,
            contract_id text NOT NULL,
            contract_version text NOT NULL,
            schema_hash text NOT NULL,
            payload bytea NOT NULL,
            metadata jsonb NOT NULL,
            status text NOT NULL,
            retry_count int NOT NULL DEFAULT 0,
            retry_after timestamptz,
            lease_token uuid,
            created_at timestamptz NOT NULL,
            updated_at timestamptz NOT NULL
        );
        CREATE INDEX idx_outbox_sweep ON outbox (status, created_at);
        INSERT INTO outbox (
            event_id, tenant_id, domain, topic, contract_id, contract_version,
            schema_hash, payload, metadata, status, created_at, updated_at
        )
        SELECT status,
               '11111111-1111-1111-1111-111111111111'::uuid,
               'migration', 'migration.event', 'migration.contract', 'v1',
               'sha256:aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa',
               'payload'::bytea, '{}'::jsonb, status,
               TIMESTAMPTZ '2024-01-01 00:00:00+00',
               TIMESTAMPTZ '2024-01-02 00:00:00+00' + ordinal * INTERVAL '1 hour'
        FROM (VALUES
            ('pending', 1), ('publishing', 2), ('published', 3), ('dlx', 4)
        ) AS states(status, ordinal);
        "#,
    )
    .execute(&store.pool)
    .await?;

    sqlx::raw_sql(include_str!(
        "../migrations/0056_add_outbox_terminal_timestamps.sql"
    ))
    .execute(&store.pool)
    .await?;

    let rows: Vec<(String, bool, bool, bool, bool)> = sqlx::query_as(
        r#"
        SELECT status,
               published_at IS NULL,
               dlx_at IS NULL,
               published_at IS NOT DISTINCT FROM updated_at,
               dlx_at IS NOT DISTINCT FROM updated_at
        FROM outbox
        ORDER BY status
        "#,
    )
    .fetch_all(&store.pool)
    .await?;
    assert_eq!(
        rows,
        vec![
            ("dlx".to_string(), true, false, false, true),
            ("pending".to_string(), true, true, false, false),
            ("published".to_string(), false, true, true, false),
            ("publishing".to_string(), true, true, false, false),
        ]
    );

    store.shutdown().await?;
    Ok(())
}

#[tokio::test(flavor = "multi_thread")]
async fn outbox_terminal_timestamp_checks_reject_invalid_state_combinations() -> TestResult {
    let (_pg, store) = connect_pg().await?;
    setup_outbox(&store).await?;

    for (suffix, status) in [
        ("legal-pending", "pending"),
        ("legal-publishing", "publishing"),
        ("legal-published", "published"),
        ("legal-dlx", "dlx"),
    ] {
        let event_id = unique_event_id(suffix);
        let entry = make_entry(&event_id);
        store
            .run_global_transaction::<_, _, sqlx::Error>(|cap| {
                Box::pin(async move {
                    let _outcome =
                        append_outbox(cap, &entry, &make_test_env("terminal-check", "event"))
                            .await
                            .map_err(test_append_error)?;
                    Ok(())
                }) as BoxFuture<'_, Result<(), sqlx::Error>>
            })
            .await?;
        set_outbox_terminal_for_test(&store, &event_id, status, 0).await?;
    }

    let invalid = [
        (
            "pending-with-published",
            "pending",
            true,
            false,
            "outbox_published_at_matches_status",
        ),
        (
            "publishing-with-dlx",
            "publishing",
            false,
            true,
            "outbox_dlx_at_matches_status",
        ),
        (
            "published-without-time",
            "published",
            false,
            false,
            "outbox_published_at_matches_status",
        ),
        (
            "published-with-dlx",
            "published",
            true,
            true,
            "outbox_dlx_at_matches_status",
        ),
        (
            "dlx-without-time",
            "dlx",
            false,
            false,
            "outbox_dlx_at_matches_status",
        ),
        (
            "dlx-with-published",
            "dlx",
            true,
            true,
            "outbox_published_at_matches_status",
        ),
    ];
    for (suffix, status, has_published_at, has_dlx_at, constraint) in invalid {
        let event_id = unique_event_id(suffix);
        let entry = make_entry(&event_id);
        store
            .run_global_transaction::<_, _, sqlx::Error>(|cap| {
                Box::pin(async move {
                    let _outcome =
                        append_outbox(cap, &entry, &make_test_env("terminal-check", "event"))
                            .await
                            .map_err(test_append_error)?;
                    Ok(())
                }) as BoxFuture<'_, Result<(), sqlx::Error>>
            })
            .await?;
        let result = sqlx::query(
            r#"
            UPDATE outbox
            SET status = $1,
                lease_token = CASE WHEN $1 = 'publishing' THEN gen_random_uuid() ELSE NULL END,
                lease_until = CASE
                    WHEN $1 = 'publishing' THEN now() + interval '60 seconds'
                    ELSE NULL
                END,
                automatic_retry_deadline = CASE
                    WHEN $1 IN ('publishing', 'published', 'dlx') THEN
                        COALESCE(automatic_retry_deadline, now() + interval '24 hours')
                    ELSE automatic_retry_deadline
                END,
                same_id_redrive_deadline = CASE
                    WHEN $1 = 'dlx' THEN
                        COALESCE(same_id_redrive_deadline, now() + interval '24 hours')
                    ELSE same_id_redrive_deadline
                END,
                published_at = CASE WHEN $2 THEN now() ELSE NULL END,
                dlx_at = CASE WHEN $3 THEN now() ELSE NULL END
            WHERE event_id = $4
            "#,
        )
        .bind(status)
        .bind(has_published_at)
        .bind(has_dlx_at)
        .bind(&event_id)
        .execute(&store.pool)
        .await;
        let Err(error) = result else {
            return Err(
                format!("invalid terminal fixture unexpectedly persisted: {suffix}").into(),
            );
        };
        assert!(
            error.to_string().contains(constraint),
            "unexpected constraint for {suffix}: {error}"
        );
    }

    store.shutdown().await?;
    Ok(())
}

#[tokio::test(flavor = "multi_thread")]
async fn outbox_terminal_timestamp_catalog_matches_current_authority() -> TestResult {
    let (_pg, store) = connect_pg().await?;
    setup_outbox(&store).await?;

    let indexdef: String = sqlx::query_scalar(
        "SELECT indexdef FROM pg_indexes WHERE schemaname = 'public' AND indexname = 'idx_outbox_sweep'",
    )
    .fetch_one(&store.pool)
    .await?;
    let normalized_index = indexdef.to_ascii_lowercase();
    assert!(normalized_index.contains("(published_at)"));
    assert!(normalized_index.contains("where (status = 'published'::text)"));
    assert!(!normalized_index.contains("created_at"));

    let sweep_def: String = sqlx::query_scalar(
        "SELECT pg_get_functiondef('rss_sweep_outbox_published(bigint)'::regprocedure)",
    )
    .fetch_one(&store.pool)
    .await?;
    assert!(sweep_def.contains("p_retain_seconds <= 0"));
    assert!(sweep_def.contains("published_at <="));
    assert!(!sweep_def.contains("created_at"));

    type FunctionSecurity = (String, String, bool, bool, bool, bool, bool);
    let functions: Vec<FunctionSecurity> = sqlx::query_as(
        r#"
        SELECT p.oid::regprocedure::text,
               owner.rolname,
               owner.rolcanlogin,
               p.prosecdef,
               COALESCE('search_path=public, pg_temp' = ANY(p.proconfig), false),
               NOT EXISTS (
                   SELECT 1
                   FROM aclexplode(COALESCE(p.proacl, acldefault('f', p.proowner))) acl
                   WHERE acl.grantee = 0 AND acl.privilege_type = 'EXECUTE'
               ),
               has_function_privilege('rss_app', p.oid, 'EXECUTE')
        FROM pg_proc p
        JOIN pg_roles owner ON owner.oid = p.proowner
        WHERE p.oid IN (
            'rss_outbox_claim_batch(text, bigint, bigint, bigint)'::regprocedure,
            'rss_outbox_publish_preflight(text, uuid, bigint, bigint, bigint)'::regprocedure,
            'rss_outbox_settle_published(text, uuid, bigint)'::regprocedure,
            'rss_outbox_settle_retry(text, uuid, bigint)'::regprocedure,
            'rss_outbox_mark_dlx(text, uuid, bigint)'::regprocedure,
            'rss_outbox_redrive(text, uuid)'::regprocedure,
            'rss_outbox_resolve_expired(text, uuid, text, text, text, text)'::regprocedure,
            'rss_sweep_outbox_published(bigint)'::regprocedure,
            'rss_outbox_sample_backlog(text)'::regprocedure
        )
        ORDER BY p.oid::regprocedure::text
        "#,
    )
    .fetch_all(&store.pool)
    .await?;
    assert_eq!(functions.len(), 9);
    for (signature, owner, owner_can_login, security_definer, fixed_path, no_public, app_exec) in
        functions
    {
        assert_eq!(owner, "rss_outbox_maintenance", "owner drift: {signature}");
        assert!(
            !owner_can_login,
            "function owner must be NOLOGIN: {signature}"
        );
        assert!(security_definer, "SECURITY DEFINER drift: {signature}");
        assert!(fixed_path, "search_path drift: {signature}");
        assert!(no_public, "PUBLIC execute drift: {signature}");
        if signature.starts_with("rss_outbox_redrive")
            || signature.starts_with("rss_outbox_resolve_expired")
        {
            assert!(
                !app_exec,
                "serving rss_app must not execute operator redrive"
            );
        } else {
            assert!(app_exec, "rss_app execute drift: {signature}");
        }
    }

    let outcome_type_acl: (String, bool, bool, bool) = sqlx::query_as(
        r#"
        SELECT owner.rolname,
               owner.rolcanlogin,
               NOT EXISTS (
                   SELECT 1
                   FROM aclexplode(COALESCE(t.typacl, acldefault('T', t.typowner))) acl
                   WHERE acl.grantee = 0 AND acl.privilege_type = 'USAGE'
               ),
               has_type_privilege('rss_app', t.oid, 'USAGE')
        FROM pg_type AS t
        JOIN pg_namespace AS n ON n.oid = t.typnamespace
        JOIN pg_roles AS owner ON owner.oid = t.typowner
        WHERE n.nspname = 'public' AND t.typname = 'rss_outbox_settlement_outcome'
        "#,
    )
    .fetch_one(&store.pool)
    .await?;
    assert_eq!(outcome_type_acl.0, "rss_outbox_maintenance");
    assert!(!outcome_type_acl.1, "settlement type owner must be NOLOGIN");
    assert!(outcome_type_acl.2, "PUBLIC type USAGE must be revoked");
    assert!(outcome_type_acl.3, "rss_app type USAGE grant missing");

    store.shutdown().await?;
    Ok(())
}

#[tokio::test(flavor = "multi_thread")]
async fn event_delivery_policy_constraints_loader_and_acl_fail_closed() -> TestResult {
    let (pg, store) = connect_pg().await?;
    setup_outbox(&store).await?;
    let app = connect_pg_rss_app_role(&pg, &store).await?;

    let privileges: (bool, bool, bool, bool, bool, bool, bool, bool) = sqlx::query_as(
        r#"
        SELECT has_table_privilege('rss_app', 'event_delivery_policy', 'SELECT'),
               has_table_privilege('rss_app', 'event_delivery_policy', 'INSERT'),
               has_table_privilege('rss_app', 'event_delivery_policy', 'UPDATE'),
               has_table_privilege('rss_app', 'event_delivery_policy', 'DELETE'),
               has_function_privilege('rss_app', 'rss_outbox_redrive(text, uuid)', 'EXECUTE'),
               has_function_privilege('rss_app', 'rss_outbox_resolve_expired(text, uuid, text, text, text, text)', 'EXECUTE'),
               has_function_privilege('rss_app', 'rss_outbox_publish_preflight(text, uuid, bigint, bigint, bigint)', 'EXECUTE'),
               has_function_privilege('rss_app', 'rss_sweep_inbox_receipts()', 'EXECUTE')
        "#,
    )
    .fetch_one(&store.pool)
    .await?;
    assert_eq!(
        privileges,
        (false, false, false, false, false, false, true, true)
    );
    let policy_owner: String = sqlx::query_scalar(
        "SELECT tableowner FROM pg_tables WHERE schemaname = 'public' AND tablename = 'event_delivery_policy'",
    )
    .fetch_one(&store.pool)
    .await?;
    assert_eq!(policy_owner, "rss_outbox_maintenance");

    let policy_probe_acl: (String, bool, bool, bool, bool, bool, bool, bool) = sqlx::query_as(
        r#"
        SELECT owner.rolname,
               owner.rolcanlogin,
               procedure.prosecdef,
               procedure.proconfig = ARRAY['search_path=pg_catalog, pg_temp']::text[],
               has_function_privilege('rss_app', procedure.oid, 'EXECUTE'),
               NOT EXISTS (
                   SELECT 1
                   FROM aclexplode(
                       COALESCE(procedure.proacl, acldefault('f', procedure.proowner))
                   ) AS acl
                   WHERE acl.grantee = 0
                     AND acl.privilege_type = 'EXECUTE'
               ),
               has_schema_privilege('rss_app', 'public', 'USAGE'),
               has_schema_privilege('rss_app', 'public', 'CREATE')
        FROM pg_proc AS procedure
        JOIN pg_namespace AS namespace ON namespace.oid = procedure.pronamespace
        JOIN pg_roles AS owner ON owner.oid = procedure.proowner
        WHERE namespace.nspname = 'public'
          AND procedure.proname = 'rss_load_event_delivery_policy'
          AND pg_get_function_identity_arguments(procedure.oid) = ''
        "#,
    )
    .fetch_one(&store.pool)
    .await?;
    assert_eq!(
        policy_probe_acl,
        (
            "rss_outbox_maintenance".to_owned(),
            false,
            true,
            true,
            true,
            true,
            true,
            false,
        ),
        "delivery policy probe must have a NOLOGIN owner, trusted search_path, exact EXECUTE grants and read-only schema access"
    );

    let resolution_acl: (bool, bool, bool, bool, bool, bool, bool, bool) = sqlx::query_as(
        r#"
        SELECT has_table_privilege('rss_app', 'outbox_expired_resolutions', 'SELECT'),
               has_table_privilege('rss_app', 'outbox_expired_resolutions', 'INSERT'),
               has_table_privilege('rss_app', 'outbox_expired_resolutions', 'UPDATE'),
               has_table_privilege('rss_app', 'outbox_expired_resolutions', 'DELETE'),
               has_table_privilege('rss_outbox_maintenance', 'outbox_expired_resolutions', 'SELECT'),
               has_table_privilege('rss_outbox_maintenance', 'outbox_expired_resolutions', 'INSERT'),
               has_table_privilege('rss_outbox_maintenance', 'outbox_expired_resolutions', 'UPDATE'),
               has_table_privilege('rss_outbox_maintenance', 'outbox_expired_resolutions', 'DELETE')
        "#,
    )
    .fetch_one(&store.pool)
    .await?;
    assert_eq!(
        resolution_acl,
        (false, false, false, false, true, true, false, false),
        "resolution evidence is maintenance-only append-only data"
    );

    let old_functions: (Option<String>, Option<String>) = sqlx::query_as(
        "SELECT to_regprocedure('rss_outbox_lease_can_publish(text,uuid,bigint)')::text, \
                to_regprocedure('rss_sweep_inbox_receipts(bigint)')::text",
    )
    .fetch_one(&store.pool)
    .await?;
    assert_eq!(old_functions, (None, None));

    let table_insert =
        sqlx::query_scalar::<_, bool>("SELECT has_table_privilege('rss_app', 'outbox', 'INSERT')")
            .fetch_one(&store.pool)
            .await?;
    assert!(
        !table_insert,
        "rss_app must not retain table-wide outbox INSERT"
    );
    let insert_columns: Vec<String> = sqlx::query_scalar(
        r#"
        SELECT column_name
        FROM information_schema.column_privileges
        WHERE table_schema = 'public'
          AND table_name = 'outbox'
          AND grantee = 'rss_app'
          AND privilege_type = 'INSERT'
        ORDER BY column_name
        "#,
    )
    .fetch_all(&store.pool)
    .await?;
    assert_eq!(
        insert_columns,
        [
            "causation_id",
            "contract_id",
            "contract_version",
            "domain",
            "event_id",
            "metadata",
            "partition_key",
            "payload",
            "schema_hash",
            "tenant_id",
            "topic",
        ],
        "rss_app may insert only immutable outbox fact inputs"
    );

    let allowed_event_id = unique_event_id("outbox-column-grant-allowed");
    let metadata = serde_json::json!({
        "tenantId": COTX_TENANT_A,
        "schemaVersion": "v1",
        "schemaHash": TEST_SCHEMA_HASH,
    })
    .to_string();
    {
        let mut tx = app.pool.begin().await?;
        sqlx::query("SELECT set_config('rss.tenant_id', $1, true)")
            .bind(COTX_TENANT_A)
            .execute(&mut *tx)
            .await?;
        sqlx::query(
            r#"
            INSERT INTO outbox (
                event_id, tenant_id, domain, topic, contract_id, contract_version, schema_hash,
                payload, metadata, partition_key, causation_id
            )
            VALUES ($1, $2::uuid, 'test', 'test.event', 'test.contract', 'v1', $3,
                    decode('00', 'hex'), $4::jsonb, NULL, NULL)
            "#,
        )
        .bind(&allowed_event_id)
        .bind(COTX_TENANT_A)
        .bind(TEST_SCHEMA_HASH)
        .bind(&metadata)
        .execute(&mut *tx)
        .await?;
        tx.commit().await?;
    }
    let allowed_state: (String, String, bool, bool) = sqlx::query_as(
        "SELECT status, same_id_delivery_phase, automatic_retry_deadline IS NULL, \
                same_id_redrive_deadline IS NULL FROM outbox WHERE event_id = $1",
    )
    .bind(&allowed_event_id)
    .fetch_one(&store.pool)
    .await?;
    assert_eq!(
        allowed_state,
        ("pending".to_string(), "automatic".to_string(), true, true),
        "fact-only INSERT must obtain the database-owned initial state"
    );

    for (event_id, forged_column, forged_value) in [
        (
            unique_event_id("outbox-forge-automatic-deadline"),
            "automatic_retry_deadline",
            "clock_timestamp() + interval '100 years'",
        ),
        (
            unique_event_id("outbox-forge-redrive-infinity"),
            "same_id_redrive_deadline",
            "timestamptz 'infinity'",
        ),
    ] {
        let mut tx = app.pool.begin().await?;
        sqlx::query("SELECT set_config('rss.tenant_id', $1, true)")
            .bind(COTX_TENANT_A)
            .execute(&mut *tx)
            .await?;
        let statement = format!(
            r#"
            INSERT INTO outbox (
                event_id, tenant_id, domain, topic, contract_id, contract_version, schema_hash,
                payload, metadata, partition_key, causation_id, {forged_column}
            )
            VALUES ($1, $2::uuid, 'test', 'test.event', 'test.contract', 'v1', $3,
                    decode('00', 'hex'), $4::jsonb, NULL, NULL, {forged_value})
            "#
        );
        let forged = sqlx::query(&statement)
            .bind(&event_id)
            .bind(COTX_TENANT_A)
            .bind(TEST_SCHEMA_HASH)
            .bind(&metadata)
            .execute(&mut *tx)
            .await;
        assert!(
            matches!(
                forged,
                Err(sqlx::Error::Database(ref error)) if error.code().as_deref() == Some("42501")
            ),
            "rss_app deadline forgery must fail by column ACL: {forged:?}"
        );
        tx.rollback().await?;
        let inserted: i64 = sqlx::query_scalar("SELECT count(*) FROM outbox WHERE event_id = $1")
            .bind(&event_id)
            .fetch_one(&store.pool)
            .await?;
        assert_eq!(
            inserted, 0,
            "rejected deadline forgery must not insert a row"
        );
    }

    for statement in [
        "UPDATE event_delivery_policy SET automatic_retry_window_seconds = 0",
        "UPDATE event_delivery_policy SET same_id_redrive_horizon_seconds = -1",
        "UPDATE event_delivery_policy SET inbox_receipt_retention_seconds = automatic_retry_window_seconds + same_id_redrive_horizon_seconds + safety_margin_seconds",
        "UPDATE event_delivery_policy SET automatic_retry_window_seconds = 9223372036854775807, same_id_redrive_horizon_seconds = 9223372036854775807, safety_margin_seconds = 9223372036854775807, inbox_receipt_retention_seconds = 9223372036854775807",
        "UPDATE event_delivery_policy SET relay_lease_ttl_ms = 0",
        "UPDATE event_delivery_policy SET relay_lease_ttl_ms = 86400001",
        "UPDATE event_delivery_policy SET relay_publish_timeout_ms = relay_lease_ttl_ms - relay_settle_timeout_ms - relay_safety_margin_ms",
        "INSERT INTO event_delivery_policy (singleton, policy_revision, automatic_retry_window_seconds, same_id_redrive_horizon_seconds, safety_margin_seconds, inbox_receipt_retention_seconds, relay_budget_revision, relay_lease_ttl_ms, relay_publish_timeout_ms, relay_settle_timeout_ms, relay_safety_margin_ms) VALUES (true, 'same-id-delivery-v1', 86400, 86400, 86400, 604800, 'relay-budget-v1', 60000, 40000, 5000, 5000)",
    ] {
        let result = sqlx::query(statement).execute(&store.pool).await;
        assert!(
            result.is_err(),
            "policy constraint must reject: {statement}"
        );
    }

    sqlx::query(
        "UPDATE event_delivery_policy SET relay_publish_timeout_ms = relay_publish_timeout_ms - 1",
    )
    .execute(&store.pool)
    .await?;
    let alternate_policy = store.load_event_delivery_policy().await?;
    let alternate_budget = RelayBudget::new(
        Duration::from_secs(60),
        Duration::from_millis(39_999),
        Duration::from_secs(5),
        Duration::from_secs(5),
    )?;
    assert!(
        alternate_policy
            .validate_relay_budget(alternate_budget)
            .is_ok()
    );
    assert!(matches!(
        alternate_policy.validate_relay_budget(test_relay_budget()),
        Err(crate::PgError::EventDeliveryPolicyMismatch)
    ));
    sqlx::query(
        "UPDATE event_delivery_policy SET relay_publish_timeout_ms = relay_publish_timeout_ms + 1",
    )
    .execute(&store.pool)
    .await?;

    sqlx::query(
        "UPDATE event_delivery_policy SET automatic_retry_window_seconds = automatic_retry_window_seconds + 1",
    )
    .execute(&store.pool)
    .await?;
    assert!(matches!(
        store.load_event_delivery_policy().await,
        Err(crate::PgError::EventDeliveryPolicyMismatch)
    ));
    sqlx::query("DELETE FROM event_delivery_policy")
        .execute(&store.pool)
        .await?;
    assert!(matches!(
        store.load_event_delivery_policy().await,
        Err(crate::PgError::EventDeliveryPolicyMismatch)
    ));

    app.shutdown().await?;
    store.shutdown().await?;
    Ok(())
}

#[tokio::test(flavor = "multi_thread")]
async fn outbox_same_id_checks_reject_each_invalid_state_without_mutation() -> TestResult {
    let (_pg, store) = connect_pg().await?;
    setup_outbox(&store).await?;
    let event_id = unique_event_id("outbox-same-id-checks");
    let entry = make_entry(&event_id);
    let env = make_test_env("same_id_check", "test.contract");
    store
        .run_global_transaction::<_, _, sqlx::Error>(|cap| {
            Box::pin(async move {
                let _outcome = append_outbox(cap, &entry, &env)
                    .await
                    .map_err(test_append_error)?;
                Ok(())
            }) as BoxFuture<'_, Result<(), sqlx::Error>>
        })
        .await?;

    type RowSnapshot = (String, String);
    let snapshot: RowSnapshot = sqlx::query_as(
        "SELECT to_jsonb(o)::text, o.xmin::text FROM outbox AS o WHERE event_id = $1",
    )
    .bind(&event_id)
    .fetch_one(&store.pool)
    .await?;
    let invalid_updates = [
        (
            "phase closed",
            "UPDATE outbox SET same_id_delivery_phase = 'invalid' WHERE event_id = $1",
        ),
        (
            "publishing requires automatic deadline",
            "UPDATE outbox SET status = 'publishing', lease_token = gen_random_uuid(), \
             lease_until = clock_timestamp() + interval '1 hour' WHERE event_id = $1",
        ),
        (
            "published requires automatic deadline",
            "UPDATE outbox SET status = 'published', published_at = clock_timestamp() \
             WHERE event_id = $1",
        ),
        (
            "dlx requires redrive deadline",
            "UPDATE outbox SET status = 'dlx', dlx_at = clock_timestamp(), \
             automatic_retry_deadline = clock_timestamp() + interval '1 hour' \
             WHERE event_id = $1",
        ),
        (
            "redrive phase requires redrive deadline",
            "UPDATE outbox SET same_id_delivery_phase = 'redrive', \
             automatic_retry_deadline = clock_timestamp() + interval '1 hour' \
             WHERE event_id = $1",
        ),
        (
            "redrive deadline requires automatic deadline",
            "UPDATE outbox SET same_id_redrive_deadline = clock_timestamp() + interval '1 hour' \
             WHERE event_id = $1",
        ),
    ];
    for (case, statement) in invalid_updates {
        let rejected = sqlx::query(statement)
            .bind(&event_id)
            .execute(&store.pool)
            .await;
        assert!(
            matches!(
                rejected,
                Err(sqlx::Error::Database(ref error)) if error.code().as_deref() == Some("23514")
            ),
            "{case} must fail by CHECK: {rejected:?}"
        );
        let after: RowSnapshot = sqlx::query_as(
            "SELECT to_jsonb(o)::text, o.xmin::text FROM outbox AS o WHERE event_id = $1",
        )
        .bind(&event_id)
        .fetch_one(&store.pool)
        .await?;
        assert_eq!(after, snapshot, "{case} must leave the row unchanged");
    }

    store.shutdown().await?;
    Ok(())
}

/// 0045：legacy reconcile_actions 的 terminal result 必须先 backfill 到 reconcile_attempt_results。
#[tokio::test(flavor = "multi_thread")]
async fn migration_0045_backfills_legacy_reconcile_action_results() -> TestResult {
    let (_pg, store) = connect_pg().await?;
    create_rss_app_role_for_migration_test(&store).await?;
    sqlx::raw_sql(include_str!(
        "../migrations/0041_create_reconcile_schema.sql"
    ))
    .execute(&store.pool)
    .await?;

    let tenant = vocab::TenantId::parse("11111111-1111-1111-1111-111111111111")?;
    let target_id: (String,) = sqlx::query_as(
        "INSERT INTO reconcile_targets (tenant_id, reconciler_id, resource_kind, resource_id) \
         VALUES ($1::uuid, 'migration-reconciler', 'device', 'migration-device') \
         RETURNING target_id::text",
    )
    .bind(tenant.to_string())
    .fetch_one(&store.pool)
    .await?;
    let attempt_id: (String,) = sqlx::query_as(
        "INSERT INTO reconcile_attempts \
         (tenant_id, target_id, lease_token, epoch, holder_id, trigger_kind) \
         VALUES ($1::uuid, $2::uuid, gen_random_uuid(), 1, 'holder-a', 'resync') \
         RETURNING attempt_id::text",
    )
    .bind(tenant.to_string())
    .bind(&target_id.0)
    .fetch_one(&store.pool)
    .await?;
    sqlx::query(
        "INSERT INTO reconcile_actions \
         (tenant_id, attempt_id, target_id, action_kind, result_label, requeue_after_ms, error_kind) \
         VALUES ($1::uuid, $2::uuid, $3::uuid, 'update', 'transient', NULL, NULL)",
    )
    .bind(tenant.to_string())
    .bind(&attempt_id.0)
    .bind(&target_id.0)
    .execute(&store.pool)
    .await?;

    sqlx::raw_sql(include_str!(
        "../migrations/0044_create_reconcile_attempt_results.sql"
    ))
    .execute(&store.pool)
    .await?;
    sqlx::raw_sql(include_str!(
        "../migrations/0045_reconcile_actions_recorded_label.sql"
    ))
    .execute(&store.pool)
    .await?;

    let result: (String, Option<String>) = sqlx::query_as(
        "SELECT result_label, error_kind \
         FROM reconcile_attempt_results \
         WHERE tenant_id = $1::uuid AND attempt_id = $2::uuid",
    )
    .bind(tenant.to_string())
    .bind(&attempt_id.0)
    .fetch_one(&store.pool)
    .await?;
    assert_eq!(
        result,
        ("transient".to_string(), Some("transient".to_string())),
        "0045 must preserve legacy terminal result before action rows become recorded"
    );

    let action: (String, Option<i64>, Option<String>) = sqlx::query_as(
        "SELECT result_label, requeue_after_ms, error_kind \
         FROM reconcile_actions \
         WHERE tenant_id = $1::uuid AND attempt_id = $2::uuid",
    )
    .bind(tenant.to_string())
    .bind(&attempt_id.0)
    .fetch_one(&store.pool)
    .await?;
    assert_eq!(action, ("recorded".to_string(), None, None));

    store.shutdown().await?;
    Ok(())
}

async fn create_rss_app_role_for_migration_test(store: &PgStore) -> TestResult {
    sqlx::raw_sql(
        r#"
        DO $$
        BEGIN
            IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'rss_app') THEN
                CREATE ROLE rss_app NOLOGIN NOBYPASSRLS;
            END IF;
            IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'rss_outbox_maintenance') THEN
                CREATE ROLE rss_outbox_maintenance NOLOGIN BYPASSRLS;
            END IF;
        END
        $$;
        GRANT USAGE ON SCHEMA public TO rss_app;
        "#,
    )
    .execute(&store.pool)
    .await?;
    Ok(())
}

fn migrations_through(max_version: i64) -> sqlx::migrate::Migrator {
    let all = sqlx::migrate!("./migrations");
    sqlx::migrate::Migrator {
        migrations: std::borrow::Cow::Owned(
            all.iter()
                .filter(|migration| migration.version <= max_version)
                .cloned()
                .collect(),
        ),
        ..sqlx::migrate::Migrator::DEFAULT
    }
}

#[tokio::test(flavor = "multi_thread")]
async fn migration_0080_rejects_unpinned_legacy_saga_instances() -> TestResult {
    let (_pg, owner) = connect_pg().await?;
    migrations_through(79).run(&owner.pool).await?;
    let tenant = uuid::Uuid::new_v4();
    let saga_id = uuid::Uuid::new_v4();
    let mut tx = owner.pool.begin().await?;
    sqlx::query("SELECT set_config('rss.tenant_id', $1, true)")
        .bind(tenant.to_string())
        .execute(&mut *tx)
        .await?;
    sqlx::query(
        "INSERT INTO saga_instances (tenant_id, saga_id, owner, contract_id) \
         VALUES ($1::uuid, $2::uuid, 'billing', 'billing.checkout')",
    )
    .bind(tenant.to_string())
    .bind(saga_id.to_string())
    .execute(&mut *tx)
    .await?;
    tx.commit().await?;

    let error = match sqlx::migrate!("./migrations").run(&owner.pool).await {
        Ok(()) => {
            return Err(std::io::Error::other(
                "legacy rows without exact identity passed migration 0080",
            )
            .into());
        }
        Err(error) => error,
    };
    assert!(
        error
            .to_string()
            .contains("cannot pin exact saga definition identity"),
        "unexpected migration failure: {error}"
    );
    let identity_columns: i64 = sqlx::query_scalar(
        "SELECT count(*) FROM information_schema.columns \
         WHERE table_schema = 'public' AND table_name = 'saga_instances' \
           AND column_name IN ('definition_version', 'definition_schema_digest', \
                               'action_registry_generation')",
    )
    .fetch_one(&owner.pool)
    .await?;
    assert_eq!(
        identity_columns, 0,
        "failed migration must roll back every new column"
    );
    Ok(())
}

#[tokio::test(flavor = "multi_thread")]
async fn migration_0079_upgrades_live_sweeper_and_sweeps_preexisting_family() -> TestResult {
    let (pg, owner) = connect_pg().await?;
    migrations_through(78).run(&owner.pool).await?;
    let app = connect_pg_rss_app_role(&pg, &owner).await?;
    let tenant = vocab::TenantId::parse(&uuid::Uuid::new_v4().to_string())?;
    let case = RefreshProducerCase::new(tenant);
    case.seed(&app, &owner).await?;
    sqlx::query(
        "UPDATE auth_grants SET expires_at = clock_timestamp() - interval '1 second' \
         WHERE tenant_id = $1::uuid AND grant_id = $2",
    )
    .bind(tenant.as_uuid().to_string())
    .bind(case.grant.id().as_str())
    .execute(&owner.pool)
    .await?;

    let predecessor: (i64, String, i64, i64) = sqlx::query_as(
        "SELECT \
         (SELECT max(version) FROM _sqlx_migrations), \
         pg_get_functiondef('rss_sweep_expired_auth_grants()'::regprocedure), \
         (SELECT count(*) FROM auth_grants WHERE tenant_id = $1::uuid AND grant_id = $2), \
         (SELECT count(*) FROM refresh_tokens WHERE tenant_id = $1::uuid AND auth_grant_id = $2)",
    )
    .bind(tenant.as_uuid().to_string())
    .bind(case.grant.id().as_str())
    .fetch_one(&owner.pool)
    .await?;
    assert_eq!(predecessor.0, 78);
    assert!(predecessor.1.contains("FOR UPDATE SKIP LOCKED"));
    assert_eq!((predecessor.2, predecessor.3), (1, 1));

    sqlx::migrate!("./migrations").run(&owner.pool).await?;

    let ledger: (i64, i64, bool) =
        sqlx::query_as("SELECT max(version), count(*), bool_and(success) FROM _sqlx_migrations")
            .fetch_one(&owner.pool)
            .await?;
    assert_eq!(ledger, (79, 79, true));

    let function: (String, String, bool, bool, Vec<String>) = sqlx::query_as(
        "SELECT \
         pg_get_functiondef(p.oid), \
         pg_get_userbyid(p.proowner), \
         p.prosecdef, \
         p.proconfig = ARRAY['search_path=pg_catalog, pg_temp']::text[], \
         ARRAY( \
             SELECT COALESCE(grantee.rolname, 'PUBLIC') \
             FROM aclexplode(COALESCE(p.proacl, acldefault('f', p.proowner))) acl \
             LEFT JOIN pg_roles grantee ON grantee.oid = acl.grantee \
             WHERE acl.privilege_type = 'EXECUTE' \
             ORDER BY COALESCE(grantee.rolname, 'PUBLIC') \
         ) \
         FROM pg_proc p \
         WHERE p.oid = 'rss_sweep_expired_auth_grants()'::regprocedure",
    )
    .fetch_one(&owner.pool)
    .await?;
    let normalized_function = function.0.split_whitespace().collect::<Vec<_>>().join(" ");
    let family_lock = normalized_function
        .find("FROM public.refresh_tokens AS refresh")
        .ok_or("upgraded sweeper must lock the refresh family")?;
    let family_delete = normalized_function
        .find("DELETE FROM public.refresh_tokens AS refresh")
        .ok_or("upgraded sweeper must explicitly delete refresh children")?;
    let root_delete = normalized_function
        .find("DELETE FROM public.auth_grants AS root")
        .ok_or("upgraded sweeper must delete the AuthGrant root")?;
    assert!(family_lock < family_delete && family_delete < root_delete);
    assert!(normalized_function.contains("ORDER BY refresh.id FOR UPDATE"));
    assert!(!normalized_function.contains("FOR UPDATE SKIP LOCKED"));
    assert_eq!(function.1, "rss_auth_grant_maintenance");
    assert!(function.2, "upgraded sweeper must remain SECURITY DEFINER");
    assert!(function.3, "upgraded sweeper search_path must remain exact");
    assert_eq!(
        function.4,
        ["rss_app", "rss_auth_grant_maintenance"],
        "upgraded function must preserve its exact EXECUTE ACL"
    );

    let table_privileges: Vec<(String, Vec<String>)> = sqlx::query_as(
        "SELECT relation.relname, ARRAY( \
             SELECT acl.privilege_type \
             FROM aclexplode(COALESCE(relation.relacl, acldefault('r', relation.relowner))) acl \
             JOIN pg_roles grantee ON grantee.oid = acl.grantee \
             WHERE grantee.rolname = 'rss_auth_grant_maintenance' \
             ORDER BY acl.privilege_type \
         ) \
         FROM pg_class relation \
         WHERE relation.oid IN ('public.auth_grants'::regclass, 'public.refresh_tokens'::regclass) \
         ORDER BY relation.relname",
    )
    .fetch_all(&owner.pool)
    .await?;
    assert_eq!(
        table_privileges,
        [
            (
                "auth_grants".to_owned(),
                vec![
                    "DELETE".to_owned(),
                    "SELECT".to_owned(),
                    "UPDATE".to_owned()
                ],
            ),
            (
                "refresh_tokens".to_owned(),
                vec![
                    "DELETE".to_owned(),
                    "SELECT".to_owned(),
                    "UPDATE".to_owned()
                ],
            ),
        ],
        "0079 must leave only the exact family-before-root maintenance capabilities"
    );

    let retained_before_sweep: (i64, i64) = sqlx::query_as(
        "SELECT \
         (SELECT count(*) FROM auth_grants WHERE tenant_id = $1::uuid AND grant_id = $2), \
         (SELECT count(*) FROM refresh_tokens WHERE tenant_id = $1::uuid AND auth_grant_id = $2)",
    )
    .bind(tenant.as_uuid().to_string())
    .bind(case.grant.id().as_str())
    .fetch_one(&owner.pool)
    .await?;
    assert_eq!(retained_before_sweep, (1, 1));
    let swept: i64 = sqlx::query_scalar("SELECT rss_sweep_expired_auth_grants()::bigint")
        .fetch_one(&app.pool)
        .await?;
    assert_eq!(swept, 1);
    let remaining: (i64, i64) = sqlx::query_as(
        "SELECT \
         (SELECT count(*) FROM auth_grants WHERE tenant_id = $1::uuid AND grant_id = $2), \
         (SELECT count(*) FROM refresh_tokens WHERE tenant_id = $1::uuid AND auth_grant_id = $2)",
    )
    .bind(tenant.as_uuid().to_string())
    .bind(case.grant.id().as_str())
    .fetch_one(&owner.pool)
    .await?;
    assert_eq!(remaining, (0, 0));

    app.shutdown().await?;
    owner.shutdown().await?;
    Ok(())
}

