    setup_config(&store).await?;
    sqlx::query(
        "INSERT INTO config_entries (tenant_id, config_key, version, value, protection_scheme) \
         VALUES ($1::uuid, $2, 1, $3, 0)",
    )
    .bind(CONFIG_TENANT)
    .bind("legacy.backfill")
    .bind("plain-v1")
    .execute(&store.pool)
    .await?;

