#[tokio::test(flavor = "multi_thread")]
async fn credential_repo_rehash_update_failure_rolls_back() -> TestResult {
    let (_pg, store) = connect_pg().await?;
    store.run_migrations().await?;
    let repo = PgCredentialRepo::from_unverified_for_test(&store);
    let tenant = cred_tenant(CRED_TENANT_A)?;
    let weak =
        secure::PasswordHash::for_test_with_params(raw_password("legacy-short"), 8 * 1024, 1, 1)?;
    let weak_phc = weak.as_str().to_owned();
    repo.insert(
        identity_scope(tenant),
        make_cred_with_hash("alice", CRED_USER_ALICE, weak, 19, tenant)?,
    )
    .await?;
    sqlx::raw_sql(
        "CREATE FUNCTION reject_credential_rehash() RETURNS trigger LANGUAGE plpgsql AS $$ \
         BEGIN RAISE EXCEPTION 'injected rehash update failure'; END $$; \
         CREATE TRIGGER reject_credential_rehash BEFORE UPDATE OF password_hash ON credentials \
         FOR EACH ROW EXECUTE FUNCTION reject_credential_rehash();",
    )
    .execute(&store.pool)
    .await?;

    assert!(
        repo.authenticate(
            identity_scope(tenant),
            login_id("alice"),
            raw_password("legacy-short"),
            cred_epoch(CRED_BASE_SECS),
        )
        .await
        .is_err(),
        "rehash UPDATE failure must fail authentication closed"
    );
    let (version, stored_phc) = owner_credential_snapshot(&store, tenant, "alice")
        .await?
        .ok_or("credential snapshot missing")?;
    assert_eq!(version, 19);
    assert_eq!(
        stored_phc, weak_phc,
        "failed transaction must roll back PHC"
    );

    store.shutdown().await?;
    Ok(())
}

#[tokio::test(flavor = "multi_thread")]
async fn credential_repo_rehash_commit_failure_rolls_back_hash_and_lockout_clear() -> TestResult {
    let (_pg, store) = connect_pg().await?;
    store.run_migrations().await?;
    let repo = PgCredentialRepo::from_unverified_for_test(&store);
    let tenant = cred_tenant(CRED_TENANT_A)?;
    let weak =
        secure::PasswordHash::for_test_with_params(raw_password("legacy-short"), 8 * 1024, 1, 1)?;
    repo.insert(
        identity_scope(tenant),
        make_cred_with_hash("alice", CRED_USER_ALICE, weak, 23, tenant)?,
    )
    .await?;
    sqlx::query(
        "UPDATE credentials SET failure_count = 4, \
         lockout_window_start = to_timestamp($3), locked_until = NULL \
         WHERE tenant_id = $1::uuid AND login = $2",
    )
    .bind(tenant.as_uuid().to_string())
    .bind("alice")
    .bind(i64::try_from(CRED_BASE_SECS - 60)?)
    .execute(&store.pool)
    .await?;
    let before = owner_credential_auth_state(&store, tenant, "alice")
        .await?
        .ok_or("credential state missing")?;
    sqlx::raw_sql(
        "CREATE SEQUENCE credential_rehash_commit_probe; \
         CREATE FUNCTION reject_credential_rehash_on_commit() RETURNS trigger LANGUAGE plpgsql AS $$ \
         BEGIN \
           IF OLD.password_hash IS DISTINCT FROM NEW.password_hash THEN \
             IF NOT EXISTS (SELECT 1 FROM credentials WHERE tenant_id = NEW.tenant_id \
             AND login = NEW.login AND failure_count = 0 \
               AND lockout_window_start IS NULL AND locked_until IS NULL) THEN \
               RAISE EXCEPTION 'rehash lockout clear missing'; \
             END IF; \
             PERFORM nextval('credential_rehash_commit_probe'); \
             RAISE EXCEPTION 'injected rehash commit failure'; \
           END IF; \
           RETURN NEW; \
         END $$; \
         CREATE CONSTRAINT TRIGGER reject_credential_rehash_on_commit AFTER UPDATE ON credentials \
         DEFERRABLE INITIALLY DEFERRED FOR EACH ROW \
         EXECUTE FUNCTION reject_credential_rehash_on_commit();",
    )
    .execute(&store.pool)
    .await?;

    let error = match repo
        .authenticate(
            identity_scope(tenant),
            login_id("alice"),
            raw_password("legacy-short"),
            cred_epoch(CRED_BASE_SECS),
        )
        .await
    {
        Err(error) => error,
        Ok(outcome) => return Err(format!("deferred trigger allowed commit: {outcome:?}").into()),
    };
    assert!(matches!(error, IdentityError::Storage(_)));
    let probe: (i64, bool) =
        sqlx::query_as("SELECT last_value, is_called FROM credential_rehash_commit_probe")
            .fetch_one(&store.pool)
            .await?;
    assert_eq!(
        probe,
        (1, true),
        "deferred trigger must observe the lockout clear before rejecting commit"
    );
    assert_eq!(
        owner_credential_auth_state(&store, tenant, "alice")
            .await?
            .ok_or("credential state missing after rollback")?,
        before,
        "commit failure must roll back PHC, version, and pre-existing lockout"
    );

    store.shutdown().await?;
    Ok(())
}

#[tokio::test(flavor = "multi_thread")]
async fn credential_repo_rehash_concurrent_logins_upgrade_weak_phc_once() -> TestResult {
    use std::sync::Arc;

    let (_pg, store) = connect_pg().await?;
    store.run_migrations().await?;
    let repo = Arc::new(PgCredentialRepo::from_unverified_for_test(&store));
    let tenant = cred_tenant(CRED_TENANT_A)?;
    let weak =
        secure::PasswordHash::for_test_with_params(raw_password("legacy-short"), 8 * 1024, 1, 1)?;
    repo.insert(
        identity_scope(tenant),
        make_cred_with_hash("alice", CRED_USER_ALICE, weak, 17, tenant)?,
    )
    .await?;

    sqlx::query(
        "CREATE TABLE credential_rehash_updates (login text PRIMARY KEY, updates integer NOT NULL DEFAULT 0)",
    )
    .execute(&store.pool)
    .await?;
    sqlx::query("INSERT INTO credential_rehash_updates (login) VALUES ('alice')")
        .execute(&store.pool)
        .await?;
    sqlx::query(
        "CREATE FUNCTION count_credential_rehash_update() RETURNS trigger LANGUAGE plpgsql AS $$ \
         BEGIN IF OLD.password_hash IS DISTINCT FROM NEW.password_hash THEN \
         UPDATE credential_rehash_updates SET updates = updates + 1 WHERE login = NEW.login; \
         END IF; RETURN NEW; END $$",
    )
    .execute(&store.pool)
    .await?;
    sqlx::query(
        "CREATE TRIGGER count_credential_rehash_update AFTER UPDATE OF password_hash ON credentials \
         FOR EACH ROW EXECUTE FUNCTION count_credential_rehash_update()",
    )
    .execute(&store.pool)
    .await?;

    let mut handles = Vec::new();
    for _ in 0..2 {
        let repo = Arc::clone(&repo);
        handles.push(tokio::spawn(async move {
            repo.authenticate(
                identity_scope(tenant),
                login_id("alice"),
                raw_password("legacy-short"),
                cred_epoch(CRED_BASE_SECS),
            )
            .await
        }));
    }
    for handle in handles {
        assert_eq!(
            authenticated_user(
                handle
                    .await
                    .map_err(|error| format!("join failed: {error}"))??
            )?,
            cred_uid(CRED_USER_ALICE)?
        );
    }

    let (rehash_updates,): (i32,) =
        sqlx::query_as("SELECT updates FROM credential_rehash_updates WHERE login = 'alice'")
            .fetch_one(&store.pool)
            .await?;
    assert_eq!(
        rehash_updates, 1,
        "row lock must serialize rehash to one PHC replacement"
    );
    let (version, upgraded_phc) = owner_credential_snapshot(&store, tenant, "alice")
        .await?
        .ok_or("credential snapshot missing")?;
    assert_eq!(
        version, 17,
        "transparent rehash must preserve business version"
    );
    assert!(!secure::PasswordHash::parse(&upgraded_phc)?.needs_rehash()?);

    store.shutdown().await?;
    Ok(())
}

// F2：未知主体登录失败**不建行 / 不建锁**——不可经枚举撑大 credentials 表（折叠列 ⇒ 无行即无锁，结构层成立）。
#[tokio::test(flavor = "multi_thread")]
async fn credential_repo_unknown_subject_creates_no_row() -> TestResult {
    let (_pg, store) = connect_pg().await?;
    store.run_migrations().await?;
    let repo = PgCredentialRepo::from_unverified_for_test(&store);
    let tenant = cred_tenant(CRED_TENANT_A)?;
    repo.insert(
        identity_scope(tenant),
        make_cred("alice", CRED_USER_ALICE, "correct", 1, tenant)?,
    )
    .await?;
    let now = cred_epoch(CRED_BASE_SECS);

    for i in 0..20 {
        assert_eq!(
            repo.authenticate(
                identity_scope(tenant),
                login_id(&format!("ghost-{i}")),
                raw_password("x"),
                now
            )
            .await?,
            AuthOutcome::RejectedUnknown
        );
    }
    // 仅 alice 一行（未知主体未建任何行 ⇒ lockout 表不随枚举增长，F2）。
    let n: (i64,) = sqlx::query_as("SELECT count(*) FROM credentials WHERE tenant_id = $1::uuid")
        .bind(CRED_TENANT_A)
        .fetch_one(&store.pool)
        .await?;
    assert_eq!(n.0, 1, "未知主体不建行（F2：lockout 表不随枚举增长）");

    store.shutdown().await?;
    Ok(())
}

// 跨租 fail-closed：A 种入并临时锁定 alice，B 仍只观察到 unknown。
#[tokio::test(flavor = "multi_thread")]
async fn credential_repo_cross_tenant_fail_closed() -> TestResult {
    let (_pg, store) = connect_pg().await?;
    store.run_migrations().await?;
    let repo = PgCredentialRepo::from_unverified_for_test(&store);
    let a = cred_tenant(CRED_TENANT_A)?;
    let b = cred_tenant(CRED_TENANT_B)?;
    repo.insert(
        identity_scope(a),
        make_cred("alice", CRED_USER_ALICE, "correct", 1, a)?,
    )
    .await?;
    let now = cred_epoch(CRED_BASE_SECS);

    // 跨租 find → None（不泄露存在性）。
    assert!(
        repo.find_by_user_id(identity_scope(b), cred_uid(CRED_USER_ALICE)?)
            .await?
            .is_none(),
        "跨租 find → None"
    );
    // 跨租 authenticate → RejectedUnknown（跨租即未知）。
    assert_eq!(
        repo.authenticate(
            identity_scope(b),
            login_id("alice"),
            raw_password("correct"),
            now
        )
        .await?,
        AuthOutcome::RejectedUnknown,
        "跨租 authenticate → RejectedUnknown"
    );
    // 在 A 锁定 alice（5 次错）；A/B 经统一 authenticate 各自 fail-closed。
    for i in 1..=5 {
        repo.authenticate(
            identity_scope(a),
            login_id("alice"),
            raw_password("wrong"),
            cred_epoch(CRED_BASE_SECS + i),
        )
        .await?;
    }
    assert_eq!(
        repo.authenticate(
            identity_scope(a),
            login_id("alice"),
            raw_password("correct"),
            cred_epoch(CRED_BASE_SECS + 5)
        )
        .await?,
        AuthOutcome::RejectedKnown
    );
    assert_eq!(
        repo.authenticate(
            identity_scope(b),
            login_id("alice"),
            raw_password("correct"),
            cred_epoch(CRED_BASE_SECS + 5)
        )
        .await?,
        AuthOutcome::RejectedUnknown
    );

    store.shutdown().await?;
    Ok(())
}

#[tokio::test(flavor = "multi_thread")]
async fn credential_repo_tenant_noop_conformance() -> TestResult {
    let (_pg, store) = connect_pg().await?;
    store.run_migrations().await?;
    let repo = PgCredentialRepo::from_unverified_for_test(&store);
    let a = cred_tenant(CRED_TENANT_A)?;
    let b = cred_tenant(CRED_TENANT_B)?;
    let alice_uid = cred_uid(CRED_USER_ALICE)?;
    let now = cred_epoch(CRED_BASE_SECS);
    let credential = make_cred("alice", CRED_USER_ALICE, "correct", 1, a)?;

    testkit::repo_conformance::assert_cross_tenant_noop(
        || async {
            repo.insert(identity_scope(a), credential).await?;
            Ok::<(), Box<dyn std::error::Error + Send + Sync>>(())
        },
        || async {
            Ok::<bool, Box<dyn std::error::Error + Send + Sync>>(
                repo.find_by_user_id(identity_scope(a), alice_uid)
                    .await?
                    .is_some(),
            )
        },
        || async {
            Ok::<bool, Box<dyn std::error::Error + Send + Sync>>(
                repo.find_by_user_id(identity_scope(b), alice_uid)
                    .await?
                    .is_some(),
            )
        },
        || async {
            let outcome = repo
                .authenticate(
                    identity_scope(b),
                    login_id("alice"),
                    raw_password("correct"),
                    now,
                )
                .await?;
            if outcome == AuthOutcome::RejectedUnknown {
                Ok::<(), Box<dyn std::error::Error + Send + Sync>>(())
            } else {
                Err(format!("cross-tenant authenticate returned {outcome:?}").into())
            }
        },
        || async {
            Ok::<bool, Box<dyn std::error::Error + Send + Sync>>(
                repo.find_by_user_id(identity_scope(a), alice_uid)
                    .await?
                    .is_some(),
            )
        },
    )
    .await?;

    store.shutdown().await?;
    Ok(())
}

// 原子推进：连续 authenticate(错) 经仓储持久化累计——未达阈值未锁，第 5 次（窗口内）达阈值锁定。
#[tokio::test(flavor = "multi_thread")]
async fn credential_repo_accumulate_failures_then_locks() -> TestResult {
    let (_pg, store) = connect_pg().await?;
    store.run_migrations().await?;
    let repo = PgCredentialRepo::from_unverified_for_test(&store);
    let a = cred_tenant(CRED_TENANT_A)?;
    repo.insert(
        identity_scope(a),
        make_cred("alice", CRED_USER_ALICE, "correct", 1, a)?,
    )
    .await?;

    for i in 1..5 {
        assert_eq!(
            repo.authenticate(
                identity_scope(a),
                login_id("alice"),
                raw_password("wrong"),
                cred_epoch(CRED_BASE_SECS + i)
            )
            .await?,
            AuthOutcome::RejectedKnown,
            "第 {i} 次失败"
        );
        assert!(
            db_locked_until(&store, CRED_TENANT_A, "alice")
                .await?
                .is_none()
        );
    }
    // 第 5 次（窗口内）→ 达阈值锁定（DB 持久化失败计数 = 5）。
    repo.authenticate(
        identity_scope(a),
        login_id("alice"),
        raw_password("wrong"),
        cred_epoch(CRED_BASE_SECS + 5),
    )
    .await?;
    assert!(
        db_locked_until(&store, CRED_TENANT_A, "alice")
            .await?
            .is_some()
    );
    assert_eq!(
        db_failure_count(&store, CRED_TENANT_A, "alice").await?,
        5,
        "失败计数持久化推进至阈值"
    );

    store.shutdown().await?;
    Ok(())
}

// lazy-unlock：TTL 内统一认证拒绝；TTL 后 authenticate 原子解锁。
#[tokio::test(flavor = "multi_thread")]
async fn credential_repo_lockout_lazy_unlocks_after_ttl() -> TestResult {
    let (_pg, store) = connect_pg().await?;
    store.run_migrations().await?;
    let repo = PgCredentialRepo::from_unverified_for_test(&store);
    let a = cred_tenant(CRED_TENANT_A)?;
    repo.insert(
        identity_scope(a),
        make_cred("alice", CRED_USER_ALICE, "correct", 1, a)?,
    )
    .await?;
    for i in 1..=5 {
        repo.authenticate(
            identity_scope(a),
            login_id("alice"),
            raw_password("wrong"),
            cred_epoch(CRED_BASE_SECS + i),
        )
        .await?;
    }
    let lock_at = CRED_BASE_SECS + 5;

    // TTL 内仍锁。
    assert_eq!(
        repo.authenticate(
            identity_scope(a),
            login_id("alice"),
            raw_password("correct"),
            cred_epoch(lock_at + LOCK_TTL_SECS - 1)
        )
        .await?,
        AuthOutcome::RejectedKnown
    );
    // TTL 后 lazy-unlock + 正确密码成功并持久化清锁。
    assert_eq!(
        authenticated_user(
            repo.authenticate(
                identity_scope(a),
                login_id("alice"),
                raw_password("correct"),
                cred_epoch(lock_at + LOCK_TTL_SECS + 1)
            )
            .await?
        )?,
        cred_uid(CRED_USER_ALICE)?
    );
    assert!(
        db_locked_until(&store, CRED_TENANT_A, "alice")
            .await?
            .is_none(),
        "lazy-unlock 持久化清 locked_until"
    );
    // 解锁后再失败从 1 重计（不沿用旧计数）→ RejectedKnown、未锁。
    let after = lock_at + LOCK_TTL_SECS + 2;
    assert_eq!(
        repo.authenticate(
            identity_scope(a),
            login_id("alice"),
            raw_password("wrong"),
            cred_epoch(after)
        )
        .await?,
        AuthOutcome::RejectedKnown
    );
    assert!(
        db_locked_until(&store, CRED_TENANT_A, "alice")
            .await?
            .is_none()
    );

    store.shutdown().await?;
    Ok(())
}

// 成功登录原子清零失败计数（authenticate 内折叠 clear——不需独立 clear 端口）。
#[tokio::test(flavor = "multi_thread")]
async fn credential_repo_authenticate_success_clears_lockout() -> TestResult {
    let (_pg, store) = connect_pg().await?;
    store.run_migrations().await?;
    let repo = PgCredentialRepo::from_unverified_for_test(&store);
    let a = cred_tenant(CRED_TENANT_A)?;
    repo.insert(
        identity_scope(a),
        make_cred("alice", CRED_USER_ALICE, "correct", 1, a)?,
    )
    .await?;

    // 4 次错（未达阈值 5，未锁）→ 失败计数持久化 = 4。
    for i in 1..=4 {
        repo.authenticate(
            identity_scope(a),
            login_id("alice"),
            raw_password("wrong"),
            cred_epoch(CRED_BASE_SECS + i),
        )
        .await?;
    }
    assert_eq!(
        db_failure_count(&store, CRED_TENANT_A, "alice").await?,
        4,
        "失败累积 4"
    );
    // 正确密码 → Authenticated + 原子清零失败计数。
    assert_eq!(
        authenticated_user(
            repo.authenticate(
                identity_scope(a),
                login_id("alice"),
                raw_password("correct"),
                cred_epoch(CRED_BASE_SECS + 5)
            )
            .await?
        )?,
        cred_uid(CRED_USER_ALICE)?
    );
    assert_eq!(
        db_failure_count(&store, CRED_TENANT_A, "alice").await?,
        0,
        "成功登录清零失败计数"
    );

    store.shutdown().await?;
    Ok(())
}

/// material-never-persisted 断言（DoD review-critical）：`information_schema.columns` 校验 credentials 列集
/// 恰为预期（含 `password_hash`，**无明文 `password` 列**）。
#[tokio::test(flavor = "multi_thread")]
async fn ts_credentials_no_plaintext_password_column() -> TestResult {
    let (_pg, store) = connect_pg().await?;
    store.run_migrations().await?;

    let rows: Vec<(String,)> = sqlx::query_as(
        "SELECT column_name FROM information_schema.columns \
         WHERE table_name = 'credentials' AND table_schema = 'public' \
         ORDER BY column_name",
    )
    .fetch_all(&store.pool)
    .await?;
    let cols: Vec<&str> = rows.iter().map(|(s,)| s.as_str()).collect();

    let expected = [
        "created_at",
        "failure_count",
        "locked_until",
        "lockout_window_start",
        "login",
        "password_hash",
        "tenant_id",
        "user_id",
        "version",
    ];
    assert_eq!(
        cols, expected,
        "credentials 列集应恰为预期（仅 PHC，无明文密码列），实际：{cols:?}"
    );
    // 显式守 DoD：无明文 password 列，仅 argon2 PHC。
    assert!(
        !cols.contains(&"password"),
        "禁止明文 password 列（明文永不落库）"
    );
    assert!(cols.contains(&"password_hash"), "仅持久化 argon2 PHC 列");

    store.shutdown().await?;
    Ok(())
}

// 已临时锁定时，正确密码也必须经统一 authenticate 拒绝且不得清锁。
#[tokio::test(flavor = "multi_thread")]
async fn credential_repo_authenticate_correct_rejects_active_lock() -> TestResult {
    let (_pg, store) = connect_pg().await?;
    store.run_migrations().await?;
    let repo = PgCredentialRepo::from_unverified_for_test(&store);
    let a = cred_tenant(CRED_TENANT_A)?;
    repo.insert(
        identity_scope(a),
        make_cred("alice", CRED_USER_ALICE, "correct", 1, a)?,
    )
    .await?;

    // 5 次错 → 达阈值锁定（locked_until 持久化非 NULL）。
    for i in 1..=5 {
        repo.authenticate(
            identity_scope(a),
            login_id("alice"),
            raw_password("wrong"),
            cred_epoch(CRED_BASE_SECS + i),
        )
        .await?;
    }
    assert!(
        db_locked_until(&store, CRED_TENANT_A, "alice")
            .await?
            .is_some(),
        "达阈值后 locked_until 持久化"
    );

    // 正确密码仍拒绝，锁定状态不变。
    assert_eq!(
        repo.authenticate(
            identity_scope(a),
            login_id("alice"),
            raw_password("correct"),
            cred_epoch(CRED_BASE_SECS + 6)
        )
        .await?,
        AuthOutcome::RejectedKnown
    );
    assert!(
        db_locked_until(&store, CRED_TENANT_A, "alice")
            .await?
            .is_some(),
        "temporary lock is not bypassed by a correct password"
    );
    assert_eq!(
        db_failure_count(&store, CRED_TENANT_A, "alice").await?,
        5,
        "temporary lock rejection preserves failure count"
    );

    store.shutdown().await?;
    Ok(())
}

/// T24：RLS 强制力证明 — credentials 表（#1316，与 T20–T23 同范式补 credentials 表 DB 层隔离）。
///
/// 以 `SET LOCAL ROLE rss_app`（非 owner，superuser 永远绕过 RLS 不适合验证）+ tenant scope 切换，验证
/// `0012` 的 RLS policy 真实生效：tenant_a scope INSERT/SELECT 成功可见；切 tenant_b → 不可见（USING 过滤）；
/// tenant_a scope 写 tenant_b 行 → WITH CHECK 拒绝。
///
/// 注：不含「未设 rss.tenant_id → 0 行」子用例——`set_config(..,is_local=true)` 在 pool 复用连接上 tx 末 revert
/// 为 placeholder GUC 默认值 `''`（非 NULL），`''::uuid` 在 USING 谓词 raise（仍 fail-closed=不泄数据，但非「0 行」），
/// 该 unset-scope 行为依赖连接是否曾被 set（pool 不可控）⇒ 不在本测试断言（T20–T23 的同款 null-scope 子用例有相同
/// 连接态依赖，见 OOS issue）。核心 RLS 强制力由下列 4 步 USING/WITH CHECK 证明已足。
#[tokio::test(flavor = "multi_thread")]
async fn t24_rls_credentials_enforces_tenant_isolation() -> TestResult {
    let (_pg, store) = connect_pg().await?;
    store.run_migrations().await?;

    // 提权：superuser 需成为 rss_app member 才能 SET LOCAL ROLE；幂等。
    sqlx::query("GRANT rss_app TO CURRENT_USER")
        .execute(&store.pool)
        .await?;

    let tenant_a = uuid::Uuid::new_v4().to_string();
    let tenant_b = uuid::Uuid::new_v4().to_string();
    let user_a = uuid::Uuid::new_v4().to_string();

    // Tx1：rss_app + tenant_a scope → INSERT tenant_a 凭据 → 成功（WITH CHECK pass）。
    {
        let mut tx = store.pool.begin().await?;
        sqlx::query("SET LOCAL ROLE rss_app")
            .execute(&mut *tx)
            .await?;
        sqlx::query("SELECT set_config('rss.tenant_id', $1, true)")
            .bind(&tenant_a)
            .execute(&mut *tx)
            .await?;
        sqlx::query(
            "INSERT INTO credentials (tenant_id, user_id, login, password_hash, version) \
             VALUES ($1::uuid, $2::uuid, 'rls-alice', 'phc-placeholder', 1)",
        )
        .bind(&tenant_a)
        .bind(&user_a)
        .execute(&mut *tx)
        .await
        .map_err(|e| format!("Tx1 INSERT tenant_a credential failed (should succeed): {e}"))?;
        sqlx::query(
            "INSERT INTO account_security_states \
             (tenant_id, user_id, status, authn_epoch, version, status_changed_at, updated_at) \
             VALUES ($1::uuid, $2::uuid, 'active', 0, 1, now(), now())",
        )
        .bind(&tenant_a)
        .bind(&user_a)
        .execute(&mut *tx)
        .await
        .map_err(|e| format!("Tx1 INSERT tenant_a security state failed: {e}"))?;
        tx.commit().await?;
    }

    // Tx2：rss_app + tenant_a scope → SELECT → 可见（USING pass）。
    {
        let mut tx = store.pool.begin().await?;
        sqlx::query("SET LOCAL ROLE rss_app")
            .execute(&mut *tx)
            .await?;
        sqlx::query("SELECT set_config('rss.tenant_id', $1, true)")
            .bind(&tenant_a)
            .execute(&mut *tx)
            .await?;
        let cnt: (i64,) =
            sqlx::query_as("SELECT count(*) FROM credentials WHERE login = 'rls-alice'")
                .fetch_one(&mut *tx)
                .await?;
        assert_eq!(cnt.0, 1, "t24: tenant_a scope — 凭据应可见（USING pass）");
        tx.rollback().await?;
    }

    // Tx3：rss_app + tenant_b scope → SELECT 同行 → 不可见（跨租 USING 过滤）。
    {
        let mut tx = store.pool.begin().await?;
        sqlx::query("SET LOCAL ROLE rss_app")
            .execute(&mut *tx)
            .await?;
        sqlx::query("SELECT set_config('rss.tenant_id', $1, true)")
            .bind(&tenant_b)
            .execute(&mut *tx)
            .await?;
        let cnt: (i64,) =
            sqlx::query_as("SELECT count(*) FROM credentials WHERE login = 'rls-alice'")
                .fetch_one(&mut *tx)
                .await?;
        assert_eq!(
            cnt.0, 0,
            "t24: tenant_b scope — 凭据应不可见（跨租 RLS 过滤）"
        );
        tx.rollback().await?;
    }

    // Tx4：rss_app + tenant_a scope，尝试写 tenant_b 凭据 → WITH CHECK 拒绝。
    {
        let mut tx = store.pool.begin().await?;
        sqlx::query("SET LOCAL ROLE rss_app")
            .execute(&mut *tx)
            .await?;
        sqlx::query("SELECT set_config('rss.tenant_id', $1, true)")
            .bind(&tenant_a)
            .execute(&mut *tx)
            .await?;
        let result = sqlx::query(
            "INSERT INTO credentials (tenant_id, user_id, login, password_hash, version) \
             VALUES ($1::uuid, $2::uuid, 'rls-bob', 'phc-placeholder', 1)",
        )
        .bind(&tenant_b) // tenant_b ≠ rss.tenant_id(=tenant_a) → WITH CHECK fail
        .bind(uuid::Uuid::new_v4().to_string())
        .execute(&mut *tx)
        .await;
        assert!(
            result.is_err(),
            "t24: WITH CHECK 应拒绝 tenant_b 写入（rss.tenant_id=tenant_a）"
        );
        tx.rollback().await?;
    }

    store.shutdown().await?;
    Ok(())
}

// DB CHECK 约束红用例（#1316 review F2）：0012 的域不变式 CHECK 拒非法行——version/failure_count 越 u32 界、
// 锁定态缺滑窗起点。证 domain `u32` 边界 + 锁定一致性已下沉为 DB 硬约束（坏迁移/外部直写不可绕）。
#[tokio::test(flavor = "multi_thread")]
async fn credential_repo_db_check_constraints_reject_invalid() -> TestResult {
    let (_pg, store) = connect_pg().await?;
    store.run_migrations().await?;
    let t = CRED_TENANT_A;
    let u = CRED_USER_ALICE;

    // 正例基线（合法行 INSERT 成功 → 证下列拒绝非因其它列约束，anti-vacuity）。
    insert_account_security_pair(&store, t, u, "ok").await?;

    // 非法：version < 0 → credentials_version_u32 拒。
    let mut neg_ver_tx = store.pool.begin().await?;
    let neg_ver = sqlx::query(
        "INSERT INTO credentials (tenant_id, user_id, login, password_hash, version) \
         VALUES ($1::uuid, $2::uuid, 'bad1', 'phc', -1)",
    )
    .bind(t)
    .bind(uuid::Uuid::new_v4().to_string())
    .execute(&mut *neg_ver_tx)
    .await;
    assert_database_constraint(neg_ver, "credentials_version_u32");
    neg_ver_tx.rollback().await?;

    // 非法：version > u32::MAX（4294967296）→ credentials_version_u32 拒。
    let mut over_ver_tx = store.pool.begin().await?;
    let over_ver = sqlx::query(
        "INSERT INTO credentials (tenant_id, user_id, login, password_hash, version) \
         VALUES ($1::uuid, $2::uuid, 'bad2', 'phc', 4294967296)",
    )
    .bind(t)
    .bind(uuid::Uuid::new_v4().to_string())
    .execute(&mut *over_ver_tx)
    .await;
    assert_database_constraint(over_ver, "credentials_version_u32");
    over_ver_tx.rollback().await?;

    // 非法：failure_count < 0 → credentials_failure_count_u32 拒。
    let mut neg_fc_tx = store.pool.begin().await?;
    let neg_fc = sqlx::query(
        "INSERT INTO credentials (tenant_id, user_id, login, password_hash, version, failure_count) \
         VALUES ($1::uuid, $2::uuid, 'bad3', 'phc', 1, -1)",
    )
    .bind(t)
    .bind(uuid::Uuid::new_v4().to_string())
    .execute(&mut *neg_fc_tx)
    .await;
    assert_database_constraint(neg_fc, "credentials_failure_count_u32");
    neg_fc_tx.rollback().await?;

    // 非法：locked_until 非空但 lockout_window_start 为空 → credentials_lock_requires_window 拒。
    let mut lock_tx = store.pool.begin().await?;
    let lock_no_window = sqlx::query(
        "INSERT INTO credentials (tenant_id, user_id, login, password_hash, version, locked_until) \
         VALUES ($1::uuid, $2::uuid, 'bad4', 'phc', 1, now())",
    )
    .bind(t)
    .bind(uuid::Uuid::new_v4().to_string())
    .execute(&mut *lock_tx)
    .await;
    assert_database_constraint(lock_no_window, "credentials_lock_requires_window");
    lock_tx.rollback().await?;

    store.shutdown().await?;
    Ok(())
}

// 并发行锁 RMW 红用例（#1316 review F1）：同 (tenant, login) 5 路并发 wrong-password authenticate——
// SELECT ... FOR UPDATE 串行化各事务 RMW，全部完成后失败计数恰 = 5（无丢更新）且达阈值锁定。
// 对标 role_repo_concurrent_save_converges（Arc<repo> + tokio::spawn 竞争同行）。
#[tokio::test(flavor = "multi_thread")]
async fn credential_repo_concurrent_failures_no_lost_update() -> TestResult {
    use std::sync::Arc;

    let (_pg, store) = connect_pg().await?;
    store.run_migrations().await?;
    let repo = Arc::new(PgCredentialRepo::from_unverified_for_test(&store));
    let a = cred_tenant(CRED_TENANT_A)?;
    repo.insert(
        identity_scope(a),
        make_cred("alice", CRED_USER_ALICE, "correct", 1, a)?,
    )
    .await?;

    // 5 路并发错密码（同一行）——同一 now，行锁强制串行 RMW（非各自读 stale 副本各 +1 丢更新）。
    let now = cred_epoch(CRED_BASE_SECS);
    let mut handles = Vec::new();
    for _ in 0..5 {
        let repo = Arc::clone(&repo);
        handles.push(tokio::spawn(async move {
            repo.authenticate(
                identity_scope(a),
                login_id("alice"),
                raw_password("wrong"),
                now,
            )
            .await
        }));
    }
    for h in handles {
        // 每路均应返回 RejectedKnown（已知主体 + 错），无 task panic / Storage 错。
        let outcome = h.await.map_err(|e| format!("join failed: {e}"))??;
        assert_eq!(
            outcome,
            AuthOutcome::RejectedKnown,
            "并发错密码各路 RejectedKnown"
        );
    }

    // 行锁串行化 ⇒ 失败计数恰 5（无丢更新）+ 达阈值锁定。
    assert_eq!(
        db_failure_count(&store, CRED_TENANT_A, "alice").await?,
        5,
        "5 路并发错密码 → 失败计数恰 5（FOR UPDATE 无丢更新）"
    );
    assert!(
        db_locked_until(&store, CRED_TENANT_A, "alice")
            .await?
            .is_some()
    );

    store.shutdown().await?;
    Ok(())
}

// ── audit_entries 集成测试 ────────────────────────────────────────────────────
//
// TA1:  genesis + 单调递增 seq
// TA2:  prev_hash 链接前驱 entry_hash
// TA3:  并发 append——no seq gap/dup（advisory lock 串行）
// TA4:  租户隔离——两租户独立 genesis
// TA5:  RLS 跨租读隔离（rss_app + tenant_b scope → 0 行）
// TA6:  list 分页游标 + has_more（5 条 ÷ page=2 → 3 页）
// TA7:  list InvalidCursor fail-closed（base64url 合法但语义无效）
// TA8:  verify_tail 增量：小窗口不覆盖被篡改 genesis → Ok；大窗口 → HashMismatch
// TA9:  recorded_at 非零 nanos 往返（regression for secs+nanos 两列设计）
// TA10: append-only——rss_app DELETE/UPDATE 被 DB 权限拒绝
// TA11: RLS NULL tenant fail-closed——未设 rss.tenant_id → 0 行
// TA12: 空租户链 list + verify_tail 均 Ok
// TA13: audit-chain key singleton pins K1 and rejects a valid-length K2 on restart

// read/write/admin traits 须在 scope 才能调用 append / list / verify_tail / verify_tenant 方法。
use audit::ports::{AuditAdminRepo as _, AuditReadRepo as _, AuditWriteRepo as _};
// base64::Engine::encode 须在 scope（URL_SAFE_NO_PAD.encode(...)）。
use base64::Engine as _;

/// 构造审计仓储（共享 pool，固定 0x5a key hasher）。
fn make_audit_repo(
    store: &PgStore,
) -> crate::PgAuditRepo<crate::audit_repo::test_support::TestVerifier> {
    crate::PgAuditRepo::from_unverified_for_test(
        store,
        crate::audit_repo::test_support::test_hasher(0x5a),
    )
}

/// 构造 audit admin 只读仓储（固定 0x5a key hasher）。
fn make_audit_admin_repo(
    store: &PgStore,
) -> crate::PgAuditAdminRepo<crate::audit_repo::test_support::TestVerifier> {
    crate::PgAuditAdminRepo::from_unverified_for_test(
        store,
        crate::audit_repo::test_support::test_hasher(0x5a),
    )
}

/// 构造审计记录（nanos 可变，其余字段固定；actor UUID 硬编码确定性 ID）。
#[allow(clippy::unwrap_used)]
// reason: 集成测试 helper——固定格式 UUID / action parse 不失败；item-level carve-out。
fn make_audit_record(tenant: vocab::TenantId, nanos: u32) -> audit::ports::AuditRecord {
    use std::time::{Duration, UNIX_EPOCH};
    audit::ports::AuditRecord {
        tenant,
        actor: ids::UserId::parse("11111111-2222-4333-8444-555555555555").unwrap(),
        actor_kind: vocab::PrincipalKind::User,
        action: vocab::Action::parse("audit:read").unwrap(),
        resource: audit::ports::ResourceRef::new("session", "sess-1"),
        outcome: audit::ports::AuditOutcome::Success,
        recorded_at: UNIX_EPOCH + Duration::new(1_700_000_000, nanos),
    }
}

/// 构造分页请求（limit ≤ 500 不失败）。
#[allow(clippy::unwrap_used)]
// reason: 集成测试 helper——limit 值由测试代码控制，均合法；item-level carve-out。
fn audit_page(limit: u16, cursor: Option<vocab::Cursor>) -> audit::ports::AuditPage {
    audit::ports::AuditPage {
        limit: vocab::Limit::new(limit).unwrap(),
        cursor,
    }
}

/// TA13: a different 32-byte verification tag under the same typed key generation is rejected.
#[cfg(feature = "integration")]
#[tokio::test(flavor = "multi_thread")]
async fn ta13_audit_chain_key_restart_rejects_wrong_secret() -> TestResult {
    let (_pg, store) = connect_pg().await?;
    store.run_migrations().await?;
    let k1 = [0x11_u8; 32];
    let k2 = [0x22_u8; 32];
    let first: bool =
        sqlx::query_scalar("SELECT rss_verify_audit_chain_key_v1(1::smallint, $1::bytea)")
            .bind(k1.as_slice())
            .fetch_one(&store.pool)
            .await?;
    let restart_same: bool =
        sqlx::query_scalar("SELECT rss_verify_audit_chain_key_v1(1::smallint, $1::bytea)")
            .bind(k1.as_slice())
            .fetch_one(&store.pool)
            .await?;
    let restart_wrong: bool =
        sqlx::query_scalar("SELECT rss_verify_audit_chain_key_v1(1::smallint, $1::bytea)")
            .bind(k2.as_slice())
            .fetch_one(&store.pool)
            .await?;
    assert!(first && restart_same);
    assert!(!restart_wrong, "K2 must not continue a ledger pinned to K1");
    store.shutdown().await?;
    Ok(())
}

/// 独立 read/write dyn capability 从同一个 provider 派生后必须观察同一 durable 链状态。
#[cfg(feature = "integration")]
#[tokio::test(flavor = "multi_thread")]
#[allow(clippy::unwrap_used)]
// reason: integration happy-path uses generated UUIDs and fixed valid test values.
async fn audit_dyn_read_write_wrappers_share_postgres_provider() -> TestResult {
    use std::sync::Arc;

    let (_pg, store) = connect_pg().await?;
    store.run_migrations().await?;
    let tenant = vocab::TenantId::parse(&uuid::Uuid::new_v4().to_string()).unwrap();
    let provider = Arc::new(make_audit_repo(&store));
    let write: Arc<audit::ports::DynAuditWriteRepo<'static>> = Arc::from(
        audit::ports::DynAuditWriteRepo::new_box(Arc::clone(&provider)),
    );
    let read: Arc<audit::ports::DynAuditReadRepo<'static>> =
        Arc::from(audit::ports::DynAuditReadRepo::new_box(provider));

    write
        .append(audit_scope(tenant), make_audit_record(tenant, 7))
        .await?;
    let result = read
        .list(audit_scope(tenant), audit_page(500, None))
        .await?;
    assert_eq!(result.entries.len(), 1);
    assert_eq!(result.entries[0].tenant(), tenant);
    read.verify_tail(audit_scope(tenant), 1).await?;

    store.shutdown().await?;
    Ok(())
}

/// TA1: genesis 条目 seq=0，连续 append seq 单调递增。
#[cfg(feature = "integration")]
#[tokio::test(flavor = "multi_thread")]
#[allow(clippy::unwrap_used)]
// reason: 集成测试 happy-path——UUID v4 生成不失败；item-level carve-out。
async fn ta1_audit_append_genesis_and_monotonic_seq() -> TestResult {
    let (_pg, store) = connect_pg().await?;
    store.run_migrations().await?;
    let tenant = vocab::TenantId::parse(&uuid::Uuid::new_v4().to_string()).unwrap();
    let repo = make_audit_repo(&store);

    repo.append(audit_scope(tenant), make_audit_record(tenant, 0))
        .await?;
    repo.append(audit_scope(tenant), make_audit_record(tenant, 0))
        .await?;
    repo.append(audit_scope(tenant), make_audit_record(tenant, 0))
        .await?;

    let result = repo
        .list(audit_scope(tenant), audit_page(500, None))
        .await?;
    assert_eq!(result.entries.len(), 3, "TA1: 应恰有 3 条");
    assert_eq!(result.entries[0].seq(), 0, "TA1: genesis seq=0");
    assert_eq!(result.entries[1].seq(), 1, "TA1: seq 单调+1");
    assert_eq!(result.entries[2].seq(), 2, "TA1: seq 单调+2");
    assert!(!result.has_more);
    assert!(result.next_cursor.is_none());

    store.shutdown().await?;
    Ok(())
}

/// TA2: 每条 prev_hash == 前一条 entry_hash，genesis prev 全零。
#[cfg(feature = "integration")]
#[tokio::test(flavor = "multi_thread")]
#[allow(clippy::unwrap_used)]
async fn ta2_audit_prev_links_to_predecessor_entry_hash() -> TestResult {
    let (_pg, store) = connect_pg().await?;
    store.run_migrations().await?;
    let tenant = vocab::TenantId::parse(&uuid::Uuid::new_v4().to_string()).unwrap();
    let repo = make_audit_repo(&store);

    for _ in 0..3 {
        repo.append(audit_scope(tenant), make_audit_record(tenant, 0))
            .await?;
    }

    let result = repo
        .list(audit_scope(tenant), audit_page(500, None))
        .await?;
    let e = &result.entries;

    assert_eq!(
        e[0].prev_hash().as_bytes(),
        &[0u8; 32],
        "TA2: genesis prev 须全零"
    );
    assert_eq!(
        e[1].prev_hash().as_bytes(),
        e[0].entry_hash().as_bytes(),
        "TA2: e[1].prev_hash 须 == e[0].entry_hash"
    );
    assert_eq!(
        e[2].prev_hash().as_bytes(),
        e[1].entry_hash().as_bytes(),
        "TA2: e[2].prev_hash 须 == e[1].entry_hash"
    );

    store.shutdown().await?;
    Ok(())
}

/// TA3: 同租户并发 append（5 task）——advisory lock 保证 no seq gap / dup。
#[cfg(feature = "integration")]
#[tokio::test(flavor = "multi_thread")]
#[allow(clippy::unwrap_used)]
async fn ta3_audit_concurrent_appends_no_seq_gap() -> TestResult {
    use std::sync::Arc;
    let (_pg, store) = connect_pg().await?;
    store.run_migrations().await?;
    let tenant = vocab::TenantId::parse(&uuid::Uuid::new_v4().to_string()).unwrap();
    let repo = Arc::new(make_audit_repo(&store));

    const N: usize = 5;
    let handles: Vec<_> = (0..N)
        .map(|_| {
            let r = Arc::clone(&repo);
            tokio::spawn(async move {
                r.append(audit_scope(tenant), make_audit_record(tenant, 0))
                    .await
            })
        })
        .collect();
    for h in handles {
        h.await.map_err(|e| format!("join error: {e}"))??;
    }

    let result = repo
        .list(audit_scope(tenant), audit_page(500, None))
        .await?;
    assert_eq!(result.entries.len(), N, "TA3: 应恰有 {N} 条");
    let mut seqs: Vec<u64> = result.entries.iter().map(|e| e.seq()).collect();
    seqs.sort_unstable();
    for (i, &s) in seqs.iter().enumerate() {
        assert_eq!(s, i as u64, "TA3: seq 须连续无 gap，i={i} s={s}");
    }

    store.shutdown().await?;
    Ok(())
}

